from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def runs(row):
        return 1 + sum(row[c] != row[c - 1] for c in range(1, w))

    # Simple horizontal bands: mark the incomplete tail of each band.
    if all(runs(row) <= 2 for row in grid):
        for r, row in enumerate(grid):
            if runs(row) != 2:
                continue
            if row[0] == bg and row[-1] != bg:
                c = next(i for i, v in enumerate(row) if v != bg)
                for j in range(c, w):
                    out[r][j] = 1
            elif row[0] != bg and row[-1] == bg:
                c = max(i for i, v in enumerate(row) if v != bg) + 1
                for j in range(c, w):
                    out[r][j] = 1
        return out

    # Otherwise, compare separated bands of the same height. One band is a
    # horizontally shifted copy of the other, with some foreground cells missing.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    best = None
    for a in range(len(bands)):
        a0, a1 = bands[a]
        for b in range(a + 1, len(bands)):
            b0, b1 = bands[b]
            if a1 - a0 != b1 - b0:
                continue
            height = a1 - a0
            for src0, dst0 in ((a0, b0), (b0, a0)):
                for shift in range(-w + 1, w):
                    expected_total = target_total = overlap = 0
                    missing_cells = []
                    for k in range(height):
                        src = {c for c, v in enumerate(grid[src0 + k]) if v != bg}
                        dst = {c for c, v in enumerate(grid[dst0 + k]) if v != bg}
                        exp = {c + shift for c in src if 0 <= c + shift < w}
                        expected_total += len(exp)
                        target_total += len(dst)
                        overlap += len(exp & dst)
                        missing_cells.extend(
                            (dst0 + k, c) for c in exp - dst
                        )
                    denom = expected_total + target_total
                    if not denom:
                        continue
                    score = 2 * overlap / denom
                    # Prefer a copy that explains missing cells rather than
                    # treating existing target cells as unexplained extras.
                    key = (score, len(missing_cells), -abs(shift))
                    if best is None or key > best[0]:
                        best = (key, missing_cells)

    if best is not None:
        for r, c in best[1]:
            out[r][c] = 1
    return out
