def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        # A terminal foreground segment isolated after an otherwise empty row.
        first_fg = next((c for c, v in enumerate(row) if v != bg), w)
        if first_fg > 0 and all(v == bg for v in row[:first_fg]):
            if all(v == bg for v in row[:first_fg]):
                for c in range(first_fg, w):
                    out[r][c] = 1
            continue

        if row[-1] != bg or all(v == bg for v in row):
            continue

        s = w - 1
        while s >= 0 and row[s] == bg:
            s -= 1
        s += 1
        if s == 0:
            continue

        # Copy the continuation from another row with the same prefix.
        template = None
        for rr, other in enumerate(grid):
            if rr != r and other[:s] == row[:s] and any(v != bg for v in other[s:]):
                template = other
                break
        if template is not None:
            for c in range(s, w):
                if row[c] == bg and template[c] != bg:
                    out[r][c] = 1
            continue

        # Otherwise extend a short repeating foreground/background motif.
        best_score = None
        best_pattern = None
        best_start = None
        for p in range(1, min(8, w) + 1):
            for start in range(max(0, s - 10), s):
                if start + p > w:
                    continue
                pattern = [row[start + k] != bg for k in range(p)]
                if not any(pattern):
                    continue

                score = -0.25 * p
                valid = True
                for c in range(start, w):
                    expected = pattern[(c - start) % p]
                    actual = row[c] != bg
                    if actual and not expected:
                        valid = False
                        break
                    if expected:
                        score += 2 if actual else -2
                    else:
                        score += 1
                if valid and (best_score is None or score > best_score):
                    best_score = score
                    best_pattern = pattern
                    best_start = start

        if best_pattern is not None:
            for c in range(s, w):
                if best_pattern[(c - best_start) % len(best_pattern)] and row[c] == bg:
                    out[r][c] = 1

    return out
