def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        # Find the trailing run of background cells.
        end = w
        while end > 0 and row[end - 1] == bg:
            end -= 1
        if end == w or end < 4:
            continue

        known = row[:end]
        # Infer a short repeating pattern from the end of the known sequence.
        for period in range(1, min(8, end // 2) + 1):
            n = min(end, max(4, 2 * period))
            suffix = known[end - n:end]
            if n < 2 * period:
                continue
            if all(suffix[i] == suffix[i % period] for i in range(n)):
                for c in range(end, w):
                    if suffix[(c - (end - n)) % period] != bg:
                        out[r][c] = 1
                break

    return out
